class Solution {
    public int[] findErrorNums(int[] nums) {
        int duplicate = -1;
        int missing = -1;

        for (int value : nums) {
            int index = Math.abs(value) - 1;
            if (nums[index] < 0) {
                duplicate = Math.abs(value);
            } else {
                nums[index] = -nums[index];
            }
        }

        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > 0) {
                missing = i + 1;
            }
        }

        return new int[]{duplicate, missing};
    }
}

class Solution {
    public int[] findErrorNums(int[] nums) {
        int n = nums.length;
        long sumDiff = 0;
        long squareDiff = 0;

        for (int i = 0; i < n; i++) {
            long expected = i + 1L;
            long actual = nums[i];
            sumDiff += actual - expected;
            squareDiff += actual * actual - expected * expected;
        }

        long sumPair = squareDiff / sumDiff;
        int duplicate = (int) ((sumDiff + sumPair) / 2);
        int missing = (int) ((sumPair - sumDiff) / 2);
        return new int[]{duplicate, missing};
    }
}

class Solution {
    public int[] findErrorNums(int[] nums) {
        int xor = 0;
        for (int i = 1; i <= nums.length; i++) {
            xor ^= i;
        }
        for (int value : nums) {
            xor ^= value;
        }

        int distinguishingBit = xor & -xor;
        int first = 0;
        int second = 0;

        for (int i = 1; i <= nums.length; i++) {
            if ((i & distinguishingBit) == 0) {
                first ^= i;
            } else {
                second ^= i;
            }
        }
        for (int value : nums) {
            if ((value & distinguishingBit) == 0) {
                first ^= value;
            } else {
                second ^= value;
            }
        }

        for (int value : nums) {
            if (value == first) {
                return new int[]{first, second};
            }
        }
        return new int[]{second, first};
    }
}

class Solution {
    public int[] findErrorNums(int[] nums) {
        java.util.Arrays.sort(nums);
        int duplicate = -1;
        int missing = 1;

        for (int i = 1; i < nums.length; i++) {
            if (nums[i] == nums[i - 1]) {
                duplicate = nums[i];
            } else if (nums[i] > nums[i - 1] + 1) {
                missing = nums[i - 1] + 1;
            }
        }
        if (nums[nums.length - 1] != nums.length) {
            missing = nums.length;
        }

        return new int[]{duplicate, missing};
    }
}
